def short_name(actor_id):
    name = by_id[actor_id]['name_ru']
    if actor_id == 'victoire-ingabire':
        return 'Виктуар Ингабире'
    if actor_id == 'paula-ingabire':
        return 'Паула Ингабире'
    if actor_id == 'francois-xavier-kalinda':
        return 'Калинда'
    if actor_id == 'jean-damascene-bizimana':
        return 'Бизимана'
    return name.split()[-1]


def savefig(fig, filename):
    fig.savefig(FIG / (filename + '.png'), dpi=190, facecolor='white')
    svg = FIG / (filename + '.svg')
    fig.savefig(svg, facecolor='white')
    svg.write_text('\n'.join(line.rstrip() for line in svg.read_text(encoding='utf-8').splitlines())+'\n', encoding='utf-8')
    plt.close(fig)


