def place_labels(ax, rows, xidx, yidx):
    """Direct names, no hidden jitter; leader lines retain exact coordinates."""
    ax.figure.canvas.draw()
    renderer = ax.figure.canvas.get_renderer()
    occupied = []
    audit = []
    # Politically important figures are placed before the crowded middle.
    priority = ['paul-kagame', 'victoire-ingabire', 'diane-rwigara', 'frank-habineza',
                'vincent-biruta', 'edouard-ngirente', 'claver-gatete', 'louise-mushikiwabo']
    order = sorted(rows, key=lambda r: (priority.index(r['actor_id']) if r['actor_id'] in priority else 100,
                                      -r['informative_traits']))
    for row in order:
        x, y = row[f'factor_{xidx+1}'], row[f'factor_{yidx+1}']
        t = ax.annotate(short_name(row['actor_id']), (x, y), xytext=(6, 6),
                        textcoords='offset points', fontsize=10.2, color='#20323f',
                        bbox={'boxstyle': 'round,pad=.10', 'fc': 'white', 'ec': 'none', 'alpha': .92})
        best = None
        for radius in (9, 20, 34, 50, 68, 86):
            for angle in (25, 155, 335, 205, 90, 270, 0, 180, 55, 125, 235, 305):
                dx, dy = radius*np.cos(np.deg2rad(angle)), radius*np.sin(np.deg2rad(angle))
                t.set_position((dx, dy))
                t.set_ha('left' if dx >= 0 else 'right')
                t.set_va('bottom' if dy >= 0 else 'top')
                box = t.get_window_extent(renderer).expanded(1.05, 1.14)
                overlap = sum(box.overlaps(b) for b in occupied)
                boundary = not (ax.bbox.contains(box.x0, box.y0) and ax.bbox.contains(box.x1, box.y1))
                # Keep names away from any dot, except the named dot itself.
                dot_hits = 0
                for rr in members:
                    if rr['actor_id'] == row['actor_id']:
                        continue
                    px, py = ax.transData.transform((rr[f'factor_{xidx+1}'], rr[f'factor_{yidx+1}']))
                    dot_hits += box.contains(px, py)
                cost = overlap*1000 + boundary*2000 + dot_hits*50 + radius/100
                if best is None or cost < best[0]:
                    best = cost, (dx, dy), box, t.get_ha(), t.get_va(), overlap, boundary
        _, offset, box, ha, va, overlap, boundary = best
        t.set_position(offset); t.set_ha(ha); t.set_va(va)
        occupied.append(box)
        ax.annotate('', (x, y), xytext=offset, textcoords='offset points',
                    arrowprops={'arrowstyle': '-', 'color': '#a8b5bd', 'lw': .55}, zorder=1)
        audit.append({'actor_id': row['actor_id'], 'overlaps_prior_labels': int(overlap), 'outside_axes': bool(boundary)})
    return audit


def draw_map(xidx, yidx, filename):
    fig, ax = plt.subplots(figsize=(13.2, 7.6))
    fig.subplots_adjust(left=.095, right=.975, bottom=.20, top=.84)
    for g in groups:
        rows = [r for r in members if r['cluster'] == g['id']]
        ax.scatter([r[f'factor_{xidx+1}'] for r in rows], [r[f'factor_{yidx+1}'] for r in rows],
                   s=65, c=COLORS[g['id']-1], edgecolor='white', linewidth=.8, zorder=3)
    vals = np.array([[r[f'factor_{xidx+1}'], r[f'factor_{yidx+1}']] for r in members])
    pad = .33
    ax.set_xlim(vals[:, 0].min()-pad, vals[:, 0].max()+pad)
    ax.set_ylim(vals[:, 1].min()-pad, vals[:, 1].max()+pad)
    ax.axhline(0, color='#d9e2e6', lw=.8, zorder=0)
    ax.axvline(0, color='#d9e2e6', lw=.8, zorder=0)
    ax.set_xlabel(f'Больше акцента: {AXES[xidx]} →', fontsize=12, labelpad=11)
    ax.set_ylabel(f'Больше акцента: {AXES[yidx]} →', fontsize=12, labelpad=11)
    ax.set_xticks([]); ax.set_yticks([])
    for s in ax.spines.values():
        s.set_visible(False)
    # 28 direct labels; retain every actor discussed when reading the map.
    essential = {'paul-kagame', 'victoire-ingabire', 'diane-rwigara', 'frank-habineza',
                 'louise-mushikiwabo', 'claver-gatete', 'edouard-ngirente', 'vincent-biruta',
                 'augustin-iyamuremye', 'mussa-fazil-harerimana', 'philippe-mpayimana'}
    ranked = sorted(members, key=lambda r: (-r['informative_traits'], r['actor_id']))
    selected = set(essential)
    for r in ranked:
        if len(selected) >= 28:
            break
        selected.add(r['actor_id'])
    label_rows = [r for r in members if r['actor_id'] in selected]
    audit = place_labels(ax, label_rows, xidx, yidx)
    fig.text(.035, .947, 'Карта политиков: ' + ('участие и развитие' if xidx == 0 else 'ценности и преемственность'),
             fontsize=21, weight='bold', color='#173446')
    fig.text(.035, .901, '37 участников • 28 подписей • цвет показывает одну из пяти условных групп', fontsize=12, color='#526672')
    handles = [Line2D([0], [0], marker='o', lw=0, color=c, markersize=7,
                      label=f'{i+1}. {s}') for i, (c, s) in enumerate(zip(COLORS, SHORT_GROUPS))]
    fig.legend(handles=handles, loc='lower center', bbox_to_anchor=(.51, .045), ncol=3,
               frameon=False, fontsize=10.2, handletextpad=.5, columnspacing=1.5)
    fig.text(.035, .013, 'Близость означает сходство описанных публичных тем. Она не доказывает союз, общую идеологию или одинаковое влияние.', fontsize=10, color='#526672')
    savefig(fig, filename)
    return {'filename': filename, 'shown': len(members), 'labelled': len(label_rows), 'label_audit': audit}


