def inline(value):
    value = html.escape(value)
    value = re.sub(r'\[([^\]]+)\]\(([^)]+)\)', r'<a href="\2">\1</a>', value)
    return re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', value)


blocks = []
def b(kind, text='', **kw):
    blocks.append({'kind': kind, 'text': text, **kw})
def h(text): b('heading', text)
def sh(text): b('subheading', text)
def p(text): b('paragraph', text)
def bullet(text): b('bullet', text)
def note(text): b('note', text)
def figure(filename, title, caption): b('figure', title, path='figures/'+filename+'.png', caption=caption)
def quote(qid):
    q = quotes[qid]
    b('quote', q['quote_ru'], original=q['quote_original'],
      attribution=f"{q['speaker_ru']} · {q['event_date']} · {q['capacity_at_event_ru']}",
      source_title=q['source_title'], source_url=q['source_url'], translation=q['translation_label'], quote_id=qid)


