def render_md():
    chunks = []
    for x in blocks:
        k, t = x['kind'], x['text']
        if k == 'title': chunks.append('# '+t)
        elif k == 'subtitle': chunks.append('*'+t.replace('\n', ' · ')+'*')
        elif k == 'heading': chunks.append('## '+t)
        elif k == 'subheading': chunks.append('### '+t)
        elif k == 'paragraph': chunks.append(t)
        elif k == 'bullet': chunks.append('- '+t)
        elif k == 'note': chunks.append('> '+t)
        elif k == 'figure': chunks.append(f"![{t}]({x['path']})\n\n**{t}.** {x['caption']}")
        elif k == 'quote':
            nested = t.replace('«', '“').replace('»', '”')
            chunks.append(f"> «{nested}»\n>\n> {x['translation']}. Оригинал: “{x['original']}”\n>\n> {x['attribution']}. [{x['source_title']}]({x['source_url']}).")
        elif k == 'table':
            chunks.append('| '+' | '.join(x['headers'])+' |\n| '+' | '.join('---' for _ in x['headers'])+' |\n'+'\n'.join('| '+' | '.join(r)+' |' for r in x['rows']))
        elif k == 'biography':
            refs = '; '.join(f"[{s['title']}]({s['url']})" for s in x['sources'])
            chunks.append(f"#### {t}\n\n{x['body']}\n\nПериод/дата: {x['period']}. {x['group']}\n\nИсточники: {refs}.")
    (OUT/'REPORT.md').write_text('\n\n'.join(chunks)+'\n', encoding='utf-8')


def render_html():
    parts = []
    for x in blocks:
        k, t = x['kind'], inline(x['text'])
        if k == 'title': parts.append('<h1>'+t+'</h1>')
        elif k == 'subtitle': parts.append('<p class="subtitle">'+t.replace('\n', '<br>')+'</p>')
        elif k == 'heading': parts.append('<h2>'+t+'</h2>')
        elif k == 'subheading': parts.append('<h3>'+t+'</h3>')
        elif k == 'paragraph': parts.append('<p>'+t+'</p>')
        elif k == 'bullet': parts.append('<p class="bullet">• '+t+'</p>')
        elif k == 'note': parts.append('<aside>'+t+'</aside>')
        elif k == 'figure': parts.append(f'<figure><img src="{x["path"]}" alt="{t}"><figcaption><strong>{t}.</strong> {inline(x["caption"])}</figcaption></figure>')
        elif k == 'quote':
            nested = t.replace('«', '“').replace('»', '”')
            parts.append(f'<blockquote>«{nested}»<small>{inline(x["translation"])}. Оригинал: “{inline(x["original"])}”</small><small>{inline(x["attribution"])}. <a href="{x["source_url"]}">{inline(x["source_title"])}</a></small></blockquote>')
        elif k == 'table':
            parts.append('<table><tr>'+''.join('<th>'+inline(v)+'</th>' for v in x['headers'])+'</tr>'+''.join('<tr>'+''.join('<td>'+inline(v)+'</td>' for v in r)+'</tr>' for r in x['rows'])+'</table>')
        elif k == 'biography':
            refs = '; '.join('<a href="'+s['url']+'">'+inline(s['title'])+'</a>' for s in x['sources'])
            parts.append(f'<article><h4>{t}</h4><p>{inline(x["body"])}</p><p class="meta">Период/дата: {inline(x["period"])}. {inline(x["group"])}</p><p class="meta">Источники: {refs}.</p></article>')
    css = 'body{font:18px/1.65 Arial,sans-serif;color:#203743;max-width:1000px;margin:50px auto;padding:0 24px}h1{font-size:38px;line-height:1.15}h2{margin-top:2em;color:#173446}h3{margin-top:1.7em}h4{font-size:20px;margin-bottom:.3em}a{color:#167d9a}aside,blockquote{background:#f2f6f8;padding:18px 24px;margin:24px 0;border-left:4px solid #167d9a}blockquote{font-size:21px}small{display:block;font-size:13px;margin-top:10px}figure{margin:30px -40px}img{width:100%;height:auto}figcaption,.meta{font-size:14px;color:#526672}table{border-collapse:collapse;width:100%;font-size:16px}td,th{border:1px solid #dbe3e7;padding:12px;text-align:left;vertical-align:top}article{border-top:1px solid #e0e7eb;margin-top:25px}.subtitle{color:#526672}.bullet{padding-left:12px}@media(max-width:1000px){figure{margin:25px 0}}@media print{body{font-size:11pt}figure,article,blockquote{break-inside:avoid}}'
    (OUT/'REPORT.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>Руанда: политологический отчёт</title><style>'+css+'</style><body>'+''.join(parts)+'</body></html>', encoding='utf-8')


def main():
    plt.rcParams.update({'font.family': 'DejaVu Sans', 'svg.fonttype': 'none'})
    draw_axes_card()
    maps = [draw_map(0, 1, 'politicians_f1_f2'), draw_map(2, 3, 'politicians_f3_f4')]
    draw_groups()
    author_report()
    write(OUT/'report_content.json', {'language': 'ru', 'blocks': blocks})
    render_md(); render_html()
    ids = [b['actor_id'] for b in blocks if b['kind'] == 'biography']
    assert len(ids) == len(set(ids)) == 42
    assert sum(g['n'] for g in groups) == 37
    assert len(quotes) == 8
    assert len([b for b in blocks if b['kind']=='quote']) == 7
    input_hashes = {n: hashlib.sha256((SOURCE/n).read_bytes()).hexdigest() for n in clusters['source_hashes']}
    assert input_hashes == clusters['source_hashes'], 'Frozen source files changed'
    receipt = {'report_version': 'political-q4-2026-10-18', 'participants': 42, 'mapped_and_grouped': 37,
               'directory_only': 5, 'dimensions': 4, 'groups': 5, 'figures': 4, 'verified_quotes_used': 7,
               'new_api_calls': 0, 'new_api_cost_usd': 0, 'source_files_unchanged': True,
               'source_hashes': input_hashes, 'maps': maps,
               'source_note': 'New contextual quotes and role checks do not rescore the frozen inputs.'}
    write(OUT/'report_validation.json', receipt)
    print(json.dumps({k:v for k,v in receipt.items() if k not in ('maps','source_hashes')}, ensure_ascii=False))


if __name__ == '__main__':
    main()
